window.kbPageData["views/entry/k-612b12d50dd774cd"] = {"key":"entry/k-612b12d50dd774cd","state":{"route":"entry/k-612b12d50dd774cd"},"node":{"id":"k-612b12d50dd774cd","mode":"k","title":"劳动密集型产业","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":["劳动密集型行业企业"],"qs":["国考 2025 副省级 申论#4"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["employment","industry"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["就业、社保与公共服务"],"资料类别":["非时政"]},"directorySummary":"劳动密集型产业是指生产经营中对劳动力投入依赖程度较高的产业。","review":{"definition":"劳动密集型产业是指生产经营中对劳动力投入依赖程度较高的产业。","explanation":"材料4中，标注员需要逐件处理文本、图片、语音和视频等数据，许多AI公司出于成本考虑将业务外包。这解释了青溪县发展数据标注产业为何能吸纳当地劳动力。面对技术要求更高的标注业务，现有队伍还需要补足专业技能，对应本题的培训和引才建议。","references":[],"evidence":"数据标注是劳动密集型产业","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"c6d2b60d41683a60","label":"劳动密集型行业企业","topic":"就业、社保与公共服务","category":"非时政","text":"4.劳动密集型行业企业\n密集型产业主要包括劳动密集型、资本密集型、技术/知识密集型、资源密集型等四种\n核心类型，这种产业分类方法体现了各产业对不同生产要素的依赖程度。\n（1）劳动密集型：指生产过程中对劳动力数量的依赖度远高于资本、技术等其他生产\n要素的产业。\n（2）资本密集型：指在生产经营中需要投入大量资本用于购置固定资产（如大型生产\n设备、厂房、生产线等）的产业。\n（3）技术/知识密集型：指以先进科学技术为核心生产要素，研发投入占比高、对专业\n技术人才依赖度强的产业。\n（4）资源密集型：指直接依托自然资源进行开采或初级加工的产业，生产过程高度依\n赖土地、矿产、森林、水等天然资源的禀赋。","source":{"doc":"6cbfb01fe723bba64b75","first":40,"last":40,"page":40,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"国考 2025 副省级 申论#4":{"paper":"国考 2025 副省级 申论","n":4,"mod":"申论","src":["7543a550935cd0cc16be.pdf",4],"asrc":["3f81b5d39fbc5b1d205d.pdf",3],"card":"20bebea5131176e9c1fce49d","links":[{"id":"k-612b12d50dd774cd","role":"解题依据","why":"这一用工特征有助于理解县域数据标注企业为何能吸纳较多劳动力，以及业务升级时为何需要提升现有队伍的专业能力。"}]}},"terms":{},"references":{},"topics":[{"slug":"industry","title":"产业升级与新质生产力"},{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-612b12d50dd774cd":[["国考 2025 副省级 申论#4"]]}};
